SELECT type, count(*) FROM authorization_policy GROUP BY 1 ORDER BY 2 DESC;
\echo ===E policies with no rules at all
SELECT count(*) AS no_rules FROM authorization_policy WHERE jsonb_array_length("credentialRules")=0 AND jsonb_array_length("privilegeRules")=0 AND (("verifiedCredentialRules" IS NULL) OR jsonb_array_length("verifiedCredentialRules")=0);
